using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.Rendering;using UnityEngine.SceneManagement;using ProjectWait.M.Elevator;
public static class ValidateInteractionScene {public static string Main(){if(Application.isPlaying)throw new Exception("Play mode must be stopped");const string path="Assets/M/Scene/Elevator_Safety_Prototype.unity";var s=EditorSceneManager.OpenScene(path,OpenSceneMode.Single);Physics.SyncTransforms();var l=UnityEngine.Object.FindFirstObjectByType<ElevatorLesson>();var c=UnityEngine.Object.FindFirstObjectByType<ElevatorDesktopControls>();var all=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var checks=new List<object>();Action<string,bool>check=(name,passed)=>checks.Add(new{name,passed});
check("Saved M scene reopened cleanly",s.path==path&&!s.isDirty);check("No missing scripts",all.All(t=>GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject)==0));check("No missing materials or unsupported shaders",all.Where(t=>t.gameObject.activeInHierarchy).SelectMany(t=>t.GetComponents<Renderer>()).All(r=>r.sharedMaterials.All(m=>m&&m.shader&&m.shader.isSupported)));check("No CodexTemp runtime dependencies",!AssetDatabase.GetDependencies(path,true).Any(p=>p.Contains("/CodexTemp/")));
check("Movement and collision enabled",c.movement&&c.movement.GetComponent<CharacterController>().enabled&&c.movement.playerCamera==l.playerCamera);check("Only custom movement owns translation",!all.SelectMany(t=>t.GetComponents<Behaviour>()).Any(b=>b&&b.enabled&&(b.GetType().FullName.Contains(".Locomotion.")||b.GetType().Name=="DynamicMoveProvider"||b.GetType().Name=="CharacterControllerDriver")));check("Reticle has CanvasRenderer",c.reticle&&c.reticle.GetComponent<CanvasRenderer>()&&!c.reticle.raycastTarget);check("HUD is screen overlay",l.view.spatial.hud.renderMode==RenderMode.ScreenSpaceOverlay);
var p=l.pauseMenu;check("Four pause buttons saved",p&&p.Buttons.Count()==4&&p.Buttons.All(b=>b));check("Title is an unwired placeholder",!p.titleButton.interactable&&p.titleButton.onClick.GetPersistentEventCount()==0);check("Pause initially hidden",!p.canvas.gameObject.activeSelf);var obs=l.GetComponentsInChildren<ElevatorObservation>(true).Where(o=>o.gameObject.activeInHierarchy).ToArray();check("All active observations have mesh silhouettes",obs.Length==13&&obs.All(o=>o.shapeHighlight&&o.shapeHighlight.shells.Length>=4));check("Every silhouette uses a projected mask",obs.All(o=>o.shapeHighlight.shells.Any(r=>r&&r.sharedMaterial.shader.name=="ProjectWait/M/Sky Highlight Mask")));check("Old rectangles disabled",obs.All(o=>!o.outline||!o.outline.enabled));check("Glow initially hidden",obs.All(o=>o.shapeHighlight.shells.All(r=>!r.enabled)));
var sh=new[]{"ElevatorSkyHighlight.shader","ElevatorSkyHighlightMask.shader","ElevatorUIOverlay.shader"}.Select(n=>AssetDatabase.LoadAssetAtPath<Shader>("Assets/M/Arts/Shaders/"+n));check("Interaction shaders compile",sh.All(v=>v&&v.isSupported&&!ShaderUtil.ShaderHasError(v)));var rendering=l.GetComponent<ElevatorSceneRendering>();check("M-scoped shadow preset saved",rendering&&rendering.scenePipeline&&AssetDatabase.GetAssetPath(rendering.scenePipeline).StartsWith("Assets/M/"));check("Global pipeline restored",!AssetDatabase.GetAssetPath(GraphicsSettings.currentRenderPipeline).StartsWith("Assets/M/Arts/Rendering/"));check("Normal time and audio restored",Time.timeScale==1&&!AudioListener.pause);check("Quit menu ended Play Mode",SessionState.GetBool("M_Elevator_Quit_QA",false));
check("Exterior courtyard is walkable",Physics.Raycast(new Vector3(-.8f,.8f,-7.2f),Vector3.down,out var hit,1.2f)&&Mathf.Abs(hit.point.y)<.08f);check("3F and cabin references preserved",Mathf.Abs(c.xrOrigin.position.y-7.92f)<.001f&&l.presentation.space.sportsCentre.sideIntercom&&l.presentation.closedDoorCollider);check("3F automatic door references saved",l.presentation.space.sportsCentre.thirdFloorAutoDoorLeft&&l.presentation.space.sportsCentre.thirdFloorAutoDoorRight);
var report=Newtonsoft.Json.JsonConvert.SerializeObject(new{success=checks.All(x=>(bool)x.GetType().GetProperty("passed").GetValue(x)),passed=checks.Count(x=>(bool)x.GetType().GetProperty("passed").GetValue(x)),checks,activeObservations=obs.Length,scene=s.path,completedUtc=DateTime.UtcNow.ToString("o")},Newtonsoft.Json.Formatting.Indented);File.WriteAllText("Assets/M/CodexTemp/ElevatorInteraction_20261030~/SceneValidation.json",report);return report;}}